#!/usr/bin/env node
/**
 * Simple migration runner (dry-run):
 * - Reads .sql files from ./migrations
 * - Sorts them lexicographically (common timestamp prefix convention)
 * - Logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

const migrationsDir = path.resolve(process.cwd(), 'migrations');

function listSqlFiles(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  return entries
    .filter((e) => e.isFile() && e.name.toLowerCase().endsWith('.sql'))
    .map((e) => e.name)
    .sort((a, b) => a.localeCompare(b));
}

function main() {
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return;
  }

  const files = listSqlFiles(migrationsDir);

  if (files.length === 0) {
    console.log('No SQL migrations found.');
    return;
  }

  for (const file of files) {
    console.log(file);
  }
}

main();

