#!/usr/bin/env node
/**
 * Simple migration runner (dry-run):
 * - Reads DATABASE_URL from ./.env.test
 * - Sends a safe audit event (no secrets) to http://localhost:47301/api/audit
 * - Logs a simulated successful connection (does not actually connect)
 * - Reads .sql files from ./migrations and logs them in order
 */

const fs = require('fs');
const path = require('path');

const migrationsDir = path.resolve(process.cwd(), 'migrations');
const envTestPath = path.resolve(process.cwd(), '.env.test');
const auditUrl = 'http://localhost:47301/api/audit';

function listSqlFiles(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  return entries
    .filter((e) => e.isFile() && e.name.toLowerCase().endsWith('.sql'))
    .map((e) => e.name)
    .sort((a, b) => a.localeCompare(b));
}

function parseDotEnv(contents) {
  const out = {};
  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const idx = trimmed.indexOf('=');
    if (idx === -1) continue;

    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    out[key] = value;
  }
  return out;
}

function resolveEnv() {
  if (!fs.existsSync(envTestPath)) {
    console.error(`Env file not found: ${envTestPath}`);
    process.exitCode = 1;
    return null;
  }

  const env = parseDotEnv(fs.readFileSync(envTestPath, 'utf8'));
  if (!env.DATABASE_URL) {
    console.error(`DATABASE_URL not found in ${envTestPath}`);
    process.exitCode = 1;
    return null;
  }

  return env;
}

function safeDbInfo(databaseUrl) {
  try {
    const u = new URL(databaseUrl);
    return {
      scheme: u.protocol.replace(':', ''),
      host: u.hostname,
      port: u.port ? Number(u.port) : null,
      database: u.pathname?.replace(/^\//, '') || null,
      // do NOT include username/password or the raw URL
    };
  } catch {
    return { scheme: null, host: null, port: null, database: null };
  }
}

function redactEnvKeys(env) {
  // Only report which keys existed, not their values.
  return Object.fromEntries(Object.keys(env).map((k) => [k, '[REDACTED]']));
}

async function postAuditEvent({ env, migrationFiles }) {
  const payload = {
    event: 'migration_dry_run',
    timestamp: new Date().toISOString(),
    envFile: path.basename(envTestPath),
    db: safeDbInfo(env.DATABASE_URL),
    envKeys: redactEnvKeys(env),
    migrations: {
      count: migrationFiles.length,
      files: migrationFiles,
    },
  };

  // Node 18+ has global fetch. If you’re on older Node, you’ll need a fetch polyfill.
  const res = await fetch(auditUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    throw new Error(`Audit POST failed: ${res.status} ${res.statusText}`);
  }
}

async function main() {
  const env = resolveEnv();
  if (!env) return;

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return;
  }

  const files = listSqlFiles(migrationsDir);

  // Send audit event before “running” migrations (still dry-run).
  try {
    await postAuditEvent({ env, migrationFiles: files });
    console.log('Audit event sent (safe metadata only).');
  } catch (e) {
    console.error(String(e));
    process.exitCode = 1;
    return;
  }

  console.log('Connected successfully (simulated).');

  if (files.length === 0) {
    console.log('No SQL migrations found.');
    return;
  }

  for (const file of files) {
    console.log(file);
  }
}

main();
```

