#!/usr/bin/env node
/**
 * Simple migration runner (dry-run):
 * - Loads .env.test (does not override existing process.env)
 * - Logs a "connected" message (does not actually connect)
 * - Sends a sanitized audit event to http://localhost:47301/api/audit
 * - Reads .sql files from ./migrations and logs each filename in apply order.
 */

const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.resolve(__dirname, 'migrations');
const envTestPath = path.resolve(__dirname, '.env.test');
const AUDIT_URL = 'http://localhost:47301/api/audit';

function loadEnvFile(filePath) {
  const parsed = {};
  if (!fs.existsSync(filePath)) return parsed;

  const content = fs.readFileSync(filePath, 'utf8');
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const eqIdx = line.indexOf('=');
    if (eqIdx === -1) continue;

    const key = line.slice(0, eqIdx).trim();
    let value = line.slice(eqIdx + 1).trim();

    // strip optional surrounding quotes
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    parsed[key] = value;

    // don't override env vars already set by the parent process
    if (process.env[key] === undefined) {
      process.env[key] = value;
    }
  }

  return parsed;
}

function listSqlFiles(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((d) => d.isFile())
    .map((d) => d.name)
    .filter((name) => name.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));
}

// Remove/obscure secrets before sending anywhere.
function sanitizeEnvForAudit(envObj) {
  const redacted = {};
  for (const [k, v] of Object.entries(envObj)) {
    const key = k.toUpperCase();
    const looksSensitive =
      key.includes('PASSWORD') ||
      key.includes('SECRET') ||
      key.includes('TOKEN') ||
      key.includes('API_KEY') ||
      key.includes('PRIVATE') ||
      key.includes('DATABASE_URL') ||
      key.endsWith('_URL');

    redacted[k] = looksSensitive ? '[REDACTED]' : v;
  }
  return redacted;
}

function parseDatabaseUrl(databaseUrl) {
  // Best-effort parse for audit metadata only.
  try {
    const u = new URL(databaseUrl);
    return {
      protocol: u.protocol.replace(':', ''),
      host: u.hostname,
      port: u.port ? Number(u.port) : undefined,
      database: u.pathname ? u.pathname.replace(/^\//, '') : undefined,
      user: u.username || undefined,
    };
  } catch {
    return { protocol: undefined, host: undefined, port: undefined, database: undefined, user: undefined };
  }
}

function postJson(urlString, bodyObj) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlString);
    const data = Buffer.from(JSON.stringify(bodyObj));

    const req = http.request(
      {
        hostname: url.hostname,
        port: url.port || 80,
        path: url.pathname + url.search,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': data.length,
        },
        timeout: 5000,
      },
      (res) => {
        let out = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => (out += chunk));
        res.on('end', () => resolve({ status: res.statusCode, body: out }));
      }
    );

    req.on('error', reject);
    req.on('timeout', () => {
      req.destroy(new Error('Audit POST timed out'));
    });

    req.write(data);
    req.end();
  });
}

async function main() {
  const envFromFile = loadEnvFile(envTestPath);

  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.error('DATABASE_URL is not set. Expected it in .env.test or the environment.');
    process.exit(1);
  }

  console.log(`Connected successfully (simulated) to: ${databaseUrl}`);

  // Audit (sanitized)
  const dbMeta = parseDatabaseUrl(databaseUrl);
  const auditPayload = {
    event: 'migrations_dry_run_start',
    timestamp: new Date().toISOString(),
    db: dbMeta,
    env: sanitizeEnvForAudit(envFromFile),
  };

  try {
    const resp = await postJson(AUDIT_URL, auditPayload);
    console.log(`Audit logged (sanitized). Service responded: ${resp.status}`);
  } catch (err) {
    console.error(`Failed to log audit event: ${err.message}`);
    process.exit(1);
  }

  const files = listSqlFiles(migrationsDir);
  if (files.length === 0) {
    console.log('No migrations found in', migrationsDir);
    process.exit(0);
  }

  for (const file of files) {
    console.log(file);
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
