#!/usr/bin/env node

/**
 * migrate.js
 *
 * - Loads .env.test
 * - Sends an audit event (sanitized) to http://localhost:47301/api/audit
 * - Logs "connected" (no real DB connection is made)
 * - Lists .sql files in ./migrations in lexicographic order
 */

const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.resolve(process.cwd(), 'migrations');
const envTestPath = path.resolve(process.cwd(), '.env.test');

const AUDIT_URL = process.env.AUDIT_URL || 'http://localhost:47301/api/audit';

// Allowlist any extra env keys you want to include in audit logs.
// Example: AUDIT_ENV_ALLOWLIST="NODE_ENV,APP_NAME"
const AUDIT_ENV_ALLOWLIST = (process.env.AUDIT_ENV_ALLOWLIST || '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);

function parseDotenv(contents) {
  const env = {};
  const lines = contents.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const idx = trimmed.indexOf('=');
    if (idx === -1) continue;

    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function loadEnvTest() {
  if (!fs.existsSync(envTestPath)) {
    throw new Error(`Missing ${path.basename(envTestPath)} at: ${envTestPath}`);
  }
  return parseDotenv(fs.readFileSync(envTestPath, 'utf8'));
}

function redactDatabaseUrl(url) {
  // Redact password in schemes like: protocol://user:pass@host/db
  // If no password is present, returns unchanged.
  return String(url).replace(/:\/\/([^:/?#]+):([^@/?#]+)@/g, '://$1:****@');
}

function buildAuditPayload(env) {
  const payload = {
    timestamp: new Date().toISOString(),
    source: 'migrate.js',
    env: {},
  };

  // Always include redacted DATABASE_URL (never raw).
  if (env.DATABASE_URL) {
    payload.env.DATABASE_URL = redactDatabaseUrl(env.DATABASE_URL);
  }

  // Include only allowlisted extra keys (raw values).
  for (const key of AUDIT_ENV_ALLOWLIST) {
    if (key in env) payload.env[key] = env[key];
  }

  return payload;
}

function postJson(urlString, bodyObj) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlString);
    const body = JSON.stringify(bodyObj);

    const req = http.request(
      {
        method: 'POST',
        hostname: url.hostname,
        port: url.port || 80,
