  const files = entries
    .filter((e) => e.isFile())
    .map((e) => e.name)
    .filter(isSqlFile)
    // Sort lexicographically to match common timestamp/sequence prefix conventions
    .sort((a, b) => a.localeCompare(b));

  for (const filename of files) {
    console.log(filename);
  }
}

main();
