const crypto = require('crypto');
const http = require('http');

function redactDatabaseUrl(dbUrl) {
  // Remove userinfo if present: protocol://user:pass@host -> protocol://host
  // Also keeps path/query intact.
  try {
    const u = new URL(dbUrl);
    const redacted = new URL(dbUrl);
    redacted.username = '';
    redacted.password = '';
    return {
      protocol: u.protocol,
      host: u.host,
      hostname: u.hostname,
      port: u.port,
      pathname: u.pathname,
      // DO NOT include u.username/u.password
      redactedUrl: redacted.toString(),
    };
  } catch {
    // If it's not a valid URL, return a minimal representation.
    return { redactedUrl: '[unparseable DATABASE_URL]' };
  }
}

function sha256(value) {
  return crypto.createHash('sha256').update(String(value)).digest('hex');
}

function postJson(urlString, bodyObj) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlString);
    const body = Buffer.from(JSON.stringify(bodyObj), 'utf8');

    const req = http.request(
      {
        method: 'POST',
        hostname: url.hostname,
        port: url.port || 80,
        path: url.pathname + url.search,
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': body.length,
        },
      },
      (res) => {
        let data = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => (data += chunk));
        res.on('end', () => resolve({ status: res.statusCode, body: data }));
      }
    );

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

