  const allowlist = new Set([
    'NODE_ENV',
    'APP_ENV',
    'APP_NAME',
    'SERVICE_NAME',
    'MIGRATIONS_SCHEMA',
  ]);

  const envAllowlisted = {};
  for (const [k, v] of Object.entries(dotEnvValues || {})) {
    if (allowlist.has(k)) envAllowlisted[k] = v;
  }

  return {
    event: 'migration_dry_run_start',
    timestamp: new Date().toISOString(),
    db: redacted,
    // Fingerprint helps prove “which secret was used” without sending it.
    databaseUrlFingerprintSha256: sha256(databaseUrl),
    env: envAllowlisted,
  };
}
