input.content:
#!/usr/bin/env node

/**
 * Simple migration runner (dry-run logger).
 *
 * - Resolves DATABASE_URL by reading it from .env.test (without overwriting existing env vars)
 * - Logs a message indicating a successful "connection" (no real DB connection is made)
 * - Reads SQL files from ./migrations and logs each filename it would apply, in order
 */

const fs = require('fs');
const path = require('path');

const migrationsDir = path.resolve(process.cwd(), 'migrations');
const envTestPath = path.resolve(process.cwd(), '.env.test');

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) return;

  const raw = fs.readFileSync(filePath, 'utf8');
  for (const line of raw.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const idx = trimmed.indexOf('=');
    if (idx === -1) continue;

    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();

    // Remove optional surrounding quotes
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    // Do not overwrite vars already set in the environment.
    if (process.env[key] === undefined) {
      process.env[key] = value;
    }
  }
}

function isSqlFile(name) {
  return name.toLowerCase().endsWith('.sql');
}

function main() {
  // Resolve DATABASE_URL from .env.test
  loadEnvFile(envTestPath);

  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.error('DATABASE_URL is not set (expected in .env.test or environment).');
    process.exitCode = 1;
    return;
  }

  // Do not actually connect—just log.
  console.log(`Connected successfully (simulated) using DATABASE_URL from ${path.basename(envTestPath)}.`);

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return;
  }

  const entries = fs.readdirSync(migrationsDir, { withFileTypes: true });

  const files = entries
    .filter((e) => e.isFile())
    .map((e) => e.name)
    .filter(isSqlFile)
    // Lexicographic sort is typical for timestamp/sequence-prefixed migration files.
    .sort((a, b) => a.localeCompare(b));

  for (const file of files) {
    console.log(file);
  }
}

main();

