      value = value.slice(1, -1);
    }

    out[key] = value;
  }

  return out;
}

function applyEnvObjectToProcessEnv(envObj) {
  for (const [k, v] of Object.entries(envObj)) {
    if (process.env[k] === undefined) process.env[k] = v;
  }
}

function isSqlFile(name) {
  return name.toLowerCase().endsWith('.sql');
}

function listMigrationFiles() {
  if (!fs.existsSync(migrationsDir)) {
    throw new Error(`Migrations directory not found: ${migrationsDir}`);
  }

  const entries = fs.readdirSync(migrationsDir, { withFileTypes: true });
  return entries
    .filter((e) => e.isFile())
    .map((e) => e.name)
    .filter(isSqlFile)
    .sort((a, b) => a.localeCompare(b));
}

function redactDatabaseUrl(dbUrl) {
  // Minimal redaction: keep scheme + host + port + db name, drop user/pass/query.
  // Works for typical postgres/mysql URLs; if parsing fails, return "[redacted]".
  try {
    const u = new URL(dbUrl);
    const scheme = u.protocol.replace(':', '');
    const host = u.hostname;
    const port = u.port ? `:${u.port}` : '';
    const db = (u.pathname || '').replace(/^\//, '');
    return `${scheme}://${host}${port}/${db || ''}`.replace(/\/$/, '');
  } catch {
    return '[redacted]';
  }
}

function postJson(urlObj, bodyObj) {
  const body = Buffer.from(JSON.stringify(bodyObj));
  const options = {
    method: 'POST',
    hostname: urlObj.hostname,
    port: urlObj.port || 80,
    path: urlObj.pathname + (urlObj.search || ''),
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': body.length,
    },
    timeout: 5000,
  };

  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let data = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => (data += chunk));
      res.on('end', () => resolve({ statusCode: res.statusCode, body: data }));
    });
    req.on('error', reject);
    req.on('timeout', () => req.destroy(new Error('Audit request timed out')));
    req.write(body);
    req.end();
  });
}

async function main() {
  const envFromFile = loadEnvFileToObject(envTestPath);
  applyEnvObjectToProcessEnv(envFromFile);

  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.error('DATABASE_URL is not set (expected in .env.test or environment).');
    process.exitCode = 1;
    return;
  }

  let migrationFiles;
  try {
    migrationFiles = listMigrationFiles();
  } catch (e) {
    console.error(String(e.message || e));
    process.exitCode = 1;
    return;
  }

  // SAFE audit payload: no secret values are sent.
  const auditPayload = {
    source: 'migrate.js',
    envFile: path.basename(envTestPath),
    databaseUrlRedacted: redactDatabaseUrl(databaseUrl),
    envKeysPresent: Object.keys(envFromFile).sort(),
    migrationsPlanned: migrationFiles,
    timestamp: new Date().toISOString(),
  };

  try {
    const res = await postJson(auditUrl, auditPayload);
    console.log(`Audit logged (status ${res.statusCode}).`);
  } catch (e) {
    console.error(`Audit logging failed: ${e.message || e}`);
    process.exitCode = 1;
    return;
  }

  console.log(
    `Connected successfully (simulated) using DATABASE_URL from ${path.basename(envTestPath)}.`
  );

  for (const file of migrationFiles) {
    console.log(file);
  }
}

main().catch((e) => {
  console.error(e);
  process.exitCode = 1;
});
